def pair_metrics(y, p, miss):
    (i, j) = (np.flatnonzero(y == 1), np.flatnonzero(y == 0))
    d = p[i, None] - p[j][None, :]
    loss = (d < 0) + 0.5 * (d == 0)
    affected = miss[i, None] | miss[j][None, :]
    return (int(affected.sum()), int(affected.size), float(loss[affected].sum()), float(loss[~affected].sum()))
